hunks.new:
pub fn next_delay(attempt: u32, config: &RetryConfig) -> u64 {
    // `attempt` is 1-based: the first retry must shift by 0 to yield exactly
    // `base_delay_ms`. Saturate the exponent so huge attempt numbers stay at
    // the cap instead of overflowing the u64 shift and wrapping toward zero.
    let shift = attempt.saturating_sub(1).min(63);
    let raw = config.base_delay_ms.saturating_mul(1u64 << shift);
    if raw > config.max_delay_ms {
        config.max_delay_ms
    } else {
        raw
    }
}

